def chain_chain_follows(chain):
    chain_dict = {}
    for a, b in chain:
        chain_dict[a] = b

    stack = [chain[0]]
    while stack:
        current = stack.pop()
        if current not in chain_dict:
            stack.append(current)
            continue

        next_item = chain_dict[current]
        stack.append(next_item)

    return ', '.join(chain)

# Example usage:
# print(chain_chain_follows(['aaa', 'bbb']))  # Should return 'aaa, bbb'
